mapper.select:
SELECT COALESCE(SUM(c.quantity), 0) FROM cart c INNER JOIN product p ON p.product_id = c.product_id WHERE c.user_id = #{userId} AND c.type = #{type}
AND c.shop_id = #{shopId}
AND CASE WHEN c.extra_data IS NULL OR c.extra_data = '' OR JSON_VALID(c.extra_data) = 0 THEN 1 WHEN JSON_UNQUOTE(JSON_EXTRACT(c.extra_data, '$.isQuick')) = 'true' THEN 0 WHEN NULLIF( JSON_UNQUOTE(JSON_EXTRACT(c.extra_data, '$.grouponPromotionId')), 'null' ) IS NOT NULL THEN 0 ELSE 1 END = 1
